using System.IO;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        const string path = "Assets/Physics/NoFriction.physicsMaterial2D";
        if (!AssetDatabase.IsValidFolder("Assets/Physics"))
            AssetDatabase.CreateFolder("Assets", "Physics");

        PhysicsMaterial2D material = AssetDatabase.LoadAssetAtPath<PhysicsMaterial2D>(path);
        if (material == null)
        {
            material = new PhysicsMaterial2D("NoFriction")
            {
                friction = 0f,
                bounciness = 0f
            };
            AssetDatabase.CreateAsset(material, path);
            result.RegisterObjectCreation(material);
            result.Log("Created NoFriction material");
        }
        else
        {
            result.RegisterObjectModification(material);
            material.friction = 0f;
            material.bounciness = 0f;
            EditorUtility.SetDirty(material);
            result.Log("Updated NoFriction friction={0} bounce={1}", material.friction, material.bounciness);
        }

        var scene = UnityEngine.SceneManagement.SceneManager.GetActiveScene();
        if (scene.path != "Assets/Scenes/TestRoom.unity")
            scene = EditorSceneManager.OpenScene("Assets/Scenes/TestRoom.unity");

        int ground = LayerMask.NameToLayer("Ground");
        int playerLayer = LayerMask.NameToLayer("Player");
        int enemyLayer = LayerMask.NameToLayer("Enemy");
        if (playerLayer >= 0 && enemyLayer >= 0)
            Physics2D.IgnoreLayerCollision(playerLayer, enemyLayer, true);
        Physics2D.gravity = new Vector2(0f, -20f);

        Collider2D[] colliders = Object.FindObjectsByType<Collider2D>(FindObjectsInactive.Include, FindObjectsSortMode.None);
        int applied = 0;
        for (int i = 0; i < colliders.Length; i++)
        {
            Collider2D col = colliders[i];
            bool isGround = col.gameObject.layer == ground;
            bool isPlayer = col.gameObject.layer == playerLayer || col.gameObject.name == "Player";
            if (!isGround && !isPlayer)
                continue;

            result.RegisterObjectModification(col.gameObject);
            col.sharedMaterial = material;
            if (col.attachedRigidbody != null)
                col.attachedRigidbody.sharedMaterial = material;
            applied++;
            result.Log("Applied NoFriction: {0}", col.gameObject);
        }

        GameObject player = GameObject.Find("Player");
        if (player != null)
        {
            MonoBehaviour[] comps = player.GetComponents<MonoBehaviour>();
            for (int i = 0; i < comps.Length; i++)
            {
                if (comps[i] != null)
                    result.Log("Player component: {0}", comps[i]);
            }
        }

        result.Log("PlayerAttack exists: " + File.Exists("Assets/Scripts/Player/PlayerAttack.cs"));
        result.Log("Friction applied count: " + applied);
        result.Log("Ignore Player-Enemy: " + Physics2D.GetIgnoreLayerCollision(playerLayer, enemyLayer));

        EditorSceneManager.MarkSceneDirty(scene);
        EditorSceneManager.SaveScene(scene);
        AssetDatabase.SaveAssets();
        result.Log("Saved TestRoom");
    }
}

